import React, { useState, useEffect } from 'react';

const COLORS = {
  bg: '#020617', card: '#0f172a', accent: '#38bdf8', 
  gold: '#fbbf24', text: '#f8fafc', muted: '#94a3b8', 
  border: '#1e293b', success: '#22c55e', danger: '#ef4444'
};

export default function App() {
  const [tab, setTab] = useState('dashboard');
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('juris_v5_data');
    return salvo ? JSON.parse(salvo) : [];
  });

  const [novoProc, setNovoProc] = useState({ 
    cliente: '', numero: '', valor: '', data: '', status: 'Ativo', area: 'Cível' 
  });

  useEffect(() => {
    localStorage.setItem('juris_v5_data', JSON.stringify(processos));
  }, [processos]);

  const addProcesso = () => {
    if (!novoProc.cliente || !novoProc.valor) return alert("Preencha os dados essenciais!");
    setProcessos([...processos, { ...novoProc, id: Date.now() }]);
    setNovoProc({ cliente: '', numero: '', valor: '', data: '', status: 'Ativo', area: 'Cível' });
    setTab('processos');
  };

  const deletarProcesso = (id) => {
    if(window.confirm("Deseja remover este caso do sistema?")) {
      setProcessos(processos.filter(p => p.id !== id));
    }
  };

  // Métricas de Inteligência
  const totalHonorarios = processos.reduce((acc, p) => acc + Number(p.valor || 0), 0);
  const ticketMedio = processos.length > 0 ? totalHonorarios / processos.length : 0;

  return (
    <div style={s.app}>
      <aside style={s.sidebar}>
        <div style={s.brand}><div style={s.brandIcon}>J</div> JurisPRO</div>
        <nav style={s.nav}>
          <div style={s.navLink(tab === 'dashboard')} onClick={() => setTab('dashboard')}>📊 Dashboard</div>
          <div style={s.navLink(tab === 'processos')} onClick={() => setTab('processos')}>📂 Gestão de Casos</div>
          <div style={s.navLink(tab === 'novo')} onClick={() => setTab('novo')}>➕ Novo Registro</div>
        </nav>
        <div style={s.licenseCard}>
          <div style={{fontSize: '10px', opacity: 0.7}}>SISTEMA OPERACIONAL</div>
          <div style={{fontSize: '12px', fontWeight: 'bold', color: COLORS.success}}>ONLINE • CRYPTO SECURE</div>
        </div>
      </aside>

      <main style={s.content}>
        <header style={s.header}>
          <div>
            <h2 style={{margin: 0}}>Inteligência Jurídica</h2>
            <p style={{color: COLORS.muted, fontSize: '14px'}}>Monitoramento de performance da banca.</p>
          </div>
          <div style={s.topActions}>
            <div style={s.dateBadge}>{new Date().toLocaleDateString()}</div>
          </div>
        </header>

        {tab === 'dashboard' && (
          <div style={s.grid}>
            <StatCard label="Patrimônio em Litígio" value={`R$ ${totalHonorarios.toLocaleString()}`} color={COLORS.success} />
            <StatCard label="Ticket Médio / Caso" value={`R$ ${ticketMedio.toLocaleString()}`} color={COLORS.gold} />
            <StatCard label="Ações em Curso" value={processos.length} color={COLORS.accent} />

            <div style={{...s.card, gridColumn: 'span 3'}}>
              <h4 style={{marginTop: 0}}>Distribuição por Área Jurídica</h4>
              <div style={{display: 'flex', gap: '20px', marginTop: '20px'}}>
                {['Cível', 'Trabalhista', 'Tributário'].map(area => {
                  const count = processos.filter(p => p.area === area).length;
                  const pct = processos.length > 0 ? (count / processos.length) * 100 : 0;
                  return (
                    <div key={area} style={{flex: 1}}>
                      <div style={{display: 'flex', justifyContent: 'space-between', fontSize: '12px', marginBottom: '8px'}}>
                        <span>{area}</span>
                        <span>{Math.round(pct)}%</span>
                      </div>
                      <div style={s.progressBg}><div style={s.progressFill(pct, area)} /></div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {tab === 'processos' && (
          <div style={s.card}>
            <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px'}}>
              <h3 style={{margin: 0}}>Carteira Ativa</h3>
              <button style={s.btnSmall} onClick={() => setTab('novo')}>+ Adicionar</button>
            </div>
            <table style={s.table}>
              <thead>
                <tr>
                  <th style={s.th}>CLIENTE</th>
                  <th style={s.th}>ÁREA</th>
                  <th style={s.th}>HONORÁRIOS</th>
                  <th style={s.th}>AÇÕES</th>
                </tr>
              </thead>
              <tbody>
                {processos.map(p => (
                  <tr key={p.id}>
                    <td style={s.td}><strong>{p.cliente}</strong></td>
                    <td style={s.td}><span style={s.areaBadge(p.area)}>{p.area}</span></td>
                    <td style={s.td}>R$ {Number(p.valor).toLocaleString()}</td>
                    <td style={s.td}>
                      <button style={s.btnDelete} onClick={() => deletarProcesso(p.id)}>Arquivar</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {tab === 'novo' && (
          <div style={{...s.card, maxWidth: '500px', margin: '0 auto'}}>
            <h3>📝 Novo Cadastro Jurídico</h3>
            <input style={s.input} placeholder="Nome do Cliente" value={novoProc.cliente} onChange={e => setNovoProc({...novoProc, cliente: e.target.value})} />
            <select style={s.input} value={novoProc.area} onChange={e => setNovoProc({...novoProc, area: e.target.value})}>
              <option value="Cível">Direito Cível</option>
              <option value="Trabalhista">Direito Trabalhista</option>
              <option value="Tributário">Direito Tributário</option>
            </select>
            <input style={s.input} type="number" placeholder="Valor (R$)" value={novoProc.valor} onChange={e => setNovoProc({...novoProc, valor: e.target.value})} />
            <button style={s.btnMain} onClick={addProcesso}>CONFIRMAR REGISTRO</button>
          </div>
        )}
      </main>
    </div>
  );
}

const StatCard = ({label, value, color}) => (
  <div style={s.card}>
    <div style={{color: COLORS.muted, fontSize: '11px', letterSpacing: '1px'}}>{label.toUpperCase()}</div>
    <div style={{fontSize: '28px', fontWeight: 'bold', color: color, margin: '15px 0'}}>{value}</div>
    <div style={{fontSize: '11px', color: COLORS.muted}}>Atualizado em tempo real</div>
  </div>
);

const s = {
  app: { display: 'flex', minHeight: '100vh', backgroundColor: COLORS.bg, color: COLORS.text, fontFamily: "'Inter', sans-serif" },
  sidebar: { width: '260px', backgroundColor: COLORS.card, borderRight: `1px solid ${COLORS.border}`, display: 'flex', flexDirection: 'column', padding: '30px 20px' },
  brand: { fontSize: '22px', fontWeight: '800', color: COLORS.accent, display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '40px' },
  brandIcon: { width: '32px', height: '32px', backgroundColor: COLORS.accent, color: 'white', borderRadius: '6px', display: 'flex', alignItems: 'center', justifyContent: 'center' },
  nav: { flex: 1 },
  navLink: (active) => ({ padding: '12px 15px', borderRadius: '10px', cursor: 'pointer', marginBottom: '8px', color: active ? COLORS.accent : COLORS.muted, backgroundColor: active ? 'rgba(56, 189, 248, 0.08)' : 'transparent', fontSize: '14px', transition: '0.2s' }),
  licenseCard: { padding: '15px', backgroundColor: '#000', borderRadius: '10px', border: `1px solid ${COLORS.border}` },
  content: { flex: 1, padding: '40px', overflowY: 'auto' },
  header: { display: 'flex', justifyContent: 'space-between', marginBottom: '40px' },
  dateBadge: { padding: '8px 15px', backgroundColor: COLORS.card, borderRadius: '8px', border: `1px solid ${COLORS.border}`, fontSize: '12px' },
  grid: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' },
  card: { backgroundColor: COLORS.card, padding: '25px', borderRadius: '16px', border: `1px solid ${COLORS.border}` },
  table: { width: '100%', borderCollapse: 'collapse' },
  th: { textAlign: 'left', padding: '12px', color: COLORS.muted, fontSize: '11px', borderBottom: `1px solid ${COLORS.border}` },
  td: { padding: '15px', borderBottom: `1px solid ${COLORS.border}`, fontSize: '13px' },
  input: { width: '100%', padding: '12px', backgroundColor: '#000', border: `1px solid ${COLORS.border}`, color: 'white', borderRadius: '8px', marginBottom: '15px' },
  btnMain: { width: '100%', padding: '15px', backgroundColor: COLORS.accent, color: '#000', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' },
  btnSmall: { padding: '8px 15px', backgroundColor: COLORS.accent, border: 'none', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer', fontSize: '12px' },
  btnDelete: { background: 'none', border: 'none', color: COLORS.danger, cursor: 'pointer', fontSize: '12px' },
  progressBg: { height: '6px', backgroundColor: '#1e293b', borderRadius: '3px', overflow: 'hidden' },
  progressFill: (pct, area) => ({ height: '100%', width: `${pct}%`, backgroundColor: area === 'Cível' ? COLORS.accent : area === 'Trabalhista' ? COLORS.gold : COLORS.success }),
  areaBadge: (area) => ({ padding: '4px 8px', borderRadius: '4px', fontSize: '10px', fontWeight: 'bold', backgroundColor: area === 'Cível' ? '#0ea5e922' : area === 'Trabalhista' ? '#eab30822' : '#22c55e22', color: area === 'Cível' ? COLORS.accent : area === 'Trabalhista' ? COLORS.gold : COLORS.success })
};
